    margin-left: auto;
    flex-shrink: 0;
}

/* ── Main message area ── */
.message-area {
    flex: 0 0 55%;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #e8e8e8;
    overflow: hidden;
    transition: flex-basis 0.2s ease;
}

.message-area.expanded {
    flex: 1 1 auto;
}

.message-header {
    padding: 12px 20px;
