    font-weight: 700;
}

.header-desc {
    font-size: 0.8rem;
    color: #616061;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 20px;
}

.loading-indicator {
    text-align: center;
    color: #888;
    font-size: 0.85rem;
    padding: 8px;
