}

/* ── Thread panel ── */
.thread-panel {
    width: 25%;
    min-width: 280px;
    max-width: 420px;
    display: flex;
    flex-direction: column;
    background: #fff;
    overflow: hidden;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
